class UpdateHashRangeKeyValidator(DepthFirstTraverser):  # type: ignore[misc]
    def __init__(
        self,
        table_key_attributes: List[str],
        expression_attribute_names: Dict[str, str] = None,
    ):
        self.table_key_attributes = table_key_attributes
        self.expression_attribute_names = expression_attribute_names or {}

    def _processing_map(
        self,
    ) -> Dict[
        Type[UpdateExpressionPath],
        Callable[[UpdateExpressionPath], UpdateExpressionPath],
    ]:
        return {UpdateExpressionPath: self.check_for_hash_or_range_key}

    def check_for_hash_or_range_key(
        self, node: UpdateExpressionPath
    ) -> UpdateExpressionPath:
        """Check that hash and range keys are not updated"""
        first_child = node.children[0]

        # Handle direct attribute names
        if isinstance(first_child, ExpressionAttribute):
            key_to_update = first_child.children[0]
            if key_to_update in self.table_key_attributes:
                raise UpdateHashRangeKeyException(key_to_update)

        # Handle ExpressionAttributeNames
        elif isinstance(first_child, ExpressionAttributeName):
            attr_placeholder = first_child.get_attribute_name_placeholder()
            if attr_placeholder in self.expression_attribute_names:
                resolved_name = self.expression_attribute_names[attr_placeholder]
                if resolved_name in self.table_key_attributes:
                    raise UpdateHashRangeKeyException(resolved_name)

        return node

